PI <- 3.141592653589793
rot <- function(angle) complex(real=cos(angle),imaginary=-sin(angle))
pow2 <- function(value) {
  result <- 1L
  while (result < value) result <- result*2L
  result
}
is_power_two <- function(value) bitwAnd(value,value-1L) == 0L
radix2 <- function(data,inverse=FALSE) {
  n <- length(data)
  values <- as.complex(data)
  bits <- as.integer(log2(n))
  if (n > 1L) for (i in seq_len(n-1L)) {
    reversed <- 0L
    t <- i
    for (unused in seq_len(bits)) {
      reversed <- 2L*reversed+t %% 2L
      t <- t %/% 2L
    }
    if (i < reversed) {
      temporary <- values[i+1L]
      values[i+1L] <- values[reversed+1L]
      values[reversed+1L] <- temporary
    }
  }
  twiddle <- rot(2*PI*(seq_len(n %/% 2L)-1L)/n)
  if (inverse) twiddle <- Conj(twiddle)
  span <- 2L
  while (span <= n) {
    stride <- n %/% span
    half <- span %/% 2L
    for (start in seq.int(0L,n-1L,by=span)) for (j in seq_len(half)-1L) {
      t <- twiddle[j*stride+1L]*values[start+j+half+1L]
      u <- values[start+j+1L]
      values[start+j+1L] <- u+t
      values[start+j+half+1L] <- u-t
    }
    span <- span*2L
  }
  if (inverse) values/n else values
}
bluestein <- function(values) {
  m <- length(values)
  q <- pow2(2L*m-1L)
  indices <- seq_len(m)-1L
  chirp <- rot(PI*((as.numeric(indices)*indices) %% (2L*m))/m)
  a <- b <- complex(q)
  for (n in indices) {
    a[n+1L] <- values[n+1L]*chirp[n+1L]
    b[n+1L] <- Conj(chirp[n+1L])
    if (n > 0L) b[q-n+1L] <- b[n+1L]
  }
  g <- radix2(radix2(a)*radix2(b),TRUE)
  chirp*g[seq_len(m)]
}
dft <- function(values) if (is_power_two(length(values))) radix2(values) else bluestein(values)
idft <- function(values) if (is_power_two(length(values))) radix2(
    values,
    TRUE
) else Conj(bluestein(Conj(values)))/length(values)
packed_real <- function(values) {
  n <- length(values)
  half <- n %/% 2L
  j <- seq_len(half)-1L
  transformed <- radix2(complex(real=values[2L*j+1L],imaginary=values[2L*j+2L]))
  result <- complex(half+1L)
  for (k in seq.int(0L,half)) {
    a <- transformed[k %% half+1L]
    b <- Conj(transformed[(half-k) %% half+1L])
    even <- (a+b)/2
    odd <- (a-b)/(2i)
    result[k+1L] <- even+rot(2*PI*k/n)*odd
  }
  result
}
convolution <- function(a,b) {
  n <- length(a)+length(b)-1L
  q <- pow2(n)
  af <- radix2(c(a,numeric(q-length(a))))
  bf <- radix2(c(b,numeric(q-length(b))))
  Re(radix2(af*bf,TRUE)[seq_len(n)])
}
chirp_z <- function(values,fs,low,high,points) {
  m <- length(values)
  step <- (high-low)/(points-1L)
  q <- pow2(m+points-1L)
  a <- b <- complex(q)
  for (n in seq_len(m)-1L) a[n+1L] <- values[n+1L]*rot(2*PI*low*n/fs)*rot(PI*step*n*n/fs)
  for (offset in seq.int(-(m-1L),points-1L)) b[offset %% q+1L] <- Conj(rot(PI*step*offset*offset/fs))
  g <- radix2(radix2(a)*radix2(b),TRUE)
  j <- seq_len(points)-1L
  rot(PI*step*j*j/fs)*g[seq_len(points)]
}

real_text <- function(value) {
  text <- sprintf("%.4f",value)
  ifelse(text == "-0.0000","0.0000",text)
}
field_text <- function(value) if (is.double(value)) real_text(value) else as.character(value)
fields <- function(...) {
  items <- list(...)
  paste(
      vapply(seq_along(items),function(i) paste0(names(items)[i],"=",field_text(items[[i]])),character(1)),
      collapse=" "
  )
}
write_lines <- function(name,lines) {
  dir.create("output",showWarnings=FALSE)
  writeLines(lines,file.path("output",name),useBytes=TRUE)
}
write_csv <- function(name,header,rows) write_lines(
    name,
    c(header,vapply(rows,function(row) paste(vapply(row,field_text,character(1)),collapse=","),character(1)))
)
shade_lines <- function(grid,fs,n,band_db) {
  maximum_value <- max(unlist(grid,use.names=FALSE))
  shades <- strsplit(" .:-=+*#%@","",fixed=TRUE)[[1L]]
  lines <- character()
  for (k in seq.int(n %/% 2L,0L)) {
    pixels <- vapply(
        grid,
        function(row) shades[max(0L,9L-floor(-20*log10(row[k+1L]/maximum_value)/band_db))+1L],
        character(1)
    )
    frequency <- real_text(k*fs/n)
    lines <- c(
        lines,
        paste0(strrep(" ",max(0L,9L-nchar(frequency))),frequency," |",paste(pixels,collapse=""),"|")
    )
  }
  lines
}

median_value <- function(values) {
  ordered <- sort(values)
  n <- length(ordered)
  if (n %% 2L) ordered[n %/% 2L+1L] else (ordered[n %/% 2L]+ordered[n %/% 2L+1L])/2
}
local_maximum <- function(
    values,
    k
) k > 0L && k < length(values)-1L && values[k+1L] > values[k] && values[k+1L] > values[k+2L]
interpolate <- function(values,k,logarithmic=TRUE) {
  if (!local_maximum(values,k)) return(c(as.numeric(k),values[k+1L]))
  entries <- values[seq.int(k,k+2L)]
  if (logarithmic) entries <- log(entries)
  left <- entries[1L]
  middle <- entries[2L]
  right <- entries[3L]
  delta <- (left-right)/(2*(left-2*middle+right))
  fitted <- middle-(left-right)*delta/4
  c(k+delta,if (logarithmic) exp(fitted) else fitted)
}
amplitude_spectrum <- function(signal,name,n) {
  weights <- window(name,n)
  weighted <- signal[seq_len(n)]*weights
  transformed <- dft(weighted)
  s1 <- ordered_sum(weights)
  bins <- seq.int(0L,n %/% 2L)
  amplitudes <- ifelse(bins == 0L | 2L*bins == n,1,2)*Mod(transformed[bins+1L])/s1
  list(weighted=weighted,transformed=transformed,amplitudes=amplitudes)
}
packed_and_error <- function(samples) {
  packed <- packed_real(samples)
  reference <- radix2(samples)
  list(values=packed,error=max(Mod(packed-reference[seq_along(packed)])))
}
welch_spectra <- function(x,y,fs,n,name) {
  weights <- window(name,n)
  energy <- ordered_sum(weights*weights)
  segments <- (length(x)-n) %/% (n %/% 2L)+1L
  count <- n %/% 2L+1L
  pxx <- pyy <- numeric(count)
  pxy <- complex(count)
  packing_error <- 0
  for (block in seq_len(segments)-1L) {
    start <- block*(n %/% 2L)
    xf <- packed_and_error(x[seq.int(start+1L,start+n)]*weights)
    yf <- packed_and_error(y[seq.int(start+1L,start+n)]*weights)
    packing_error <- max(packing_error,xf$error,yf$error)
    for (k in seq_len(count)) {
      pxx[k] <- pxx[k]+Mod(xf$values[k])^2
      pyy[k] <- pyy[k]+Mod(yf$values[k])^2
      pxy[k] <- pxy[k]+Conj(xf$values[k])*yf$values[k]
    }
  }
  bins <- seq.int(0L,n %/% 2L)
  psd <- ifelse(bins == 0L | bins == n %/% 2L,1,2)*pxx/(segments*fs*energy)
  list(segments=segments,psd=psd,coherence=Mod(pxy)^2/(pxx*pyy),transfer=pxy/pxx,packing_error=packing_error)
}
spectrogram_magnitudes <- function(signal,n,hop,name) {
  weights <- window(name,n)
  frames <- (length(signal)-n) %/% hop+1L
  grid <- list()
  error <- 0
  for (t in seq_len(frames)-1L) {
    transformed <- packed_and_error(signal[seq.int(t*hop+1L,t*hop+n)]*weights)
    grid[[t+1L]] <- Mod(transformed$values)
    error <- max(error,transformed$error)
  }
  list(grid=grid,error=error)
}

WINDOW_ORDER <- c("rectangular","hann","hamming","blackman","flattop")
COEFFICIENTS <- list(
    rectangular=1,
    hann=c(0.5,0.5),
    hamming=c(0.54,0.46),
    blackman=c(0.42,0.5,0.08),
    flattop=c(0.21557895,0.41663158,0.277263158,0.083578947,0.006947368)
)
ordered_sum <- function(values) {
  total <- 0
  for (value in values) total <- total+value
  total
}
window <- function(name,n) {
  coefficients <- COEFFICIENTS[[name]]
  vapply(
      seq_len(n)-1L,
      function(i) ordered_sum(vapply(
          seq_along(coefficients)-1L,
          function(j) (-1)^j*coefficients[j+1L]*cos(2*PI*j*i/n),
          numeric(1)
      )),
      numeric(1)
  )
}
figures <- function(values,fs) {
  n <- length(values)
  s1 <- ordered_sum(values)
  s2 <- ordered_sum(values*values)
  magnitude <- Mod(ordered_sum(values*rot(PI*(seq_len(n)-1L)/n)))
  enbw <- n*s2/(s1*s1)
  list(s1=s1,s2=s2,coherent_gain=s1/n,enbw_bins=enbw,enbw_hz=enbw*fs/n,scalloping_db=-20*log10(magnitude/s1))
}
